package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonStreamContext;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FilteringParserDelegate#nextToken.
 * Aiming for high branch and line coverage.
 */
public class FilteringParserDelegate_nextToken_TriageGen0Test {

    private JsonParser delegate;
    private TokenFilter filter;
    private TokenFilterContext headContext;
    private FilteringParserDelegate delegateUnderTest;

    // Accessing protected methods/fields via a subclass for testing purposes
    private static class TestableFilteringParserDelegate extends FilteringParserDelegate {
        public TestableFilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches) {
            super(p, f, includePath, allowMultipleMatches);
        }

        // Expose protected methods to verify logic paths
        @Override
        protected JsonToken _nextToken2() throws IOException {
            return JsonToken.VALUE_STRING; // Mocked return for coverage
        }

        @Override
        protected JsonToken _nextTokenWithBuffering(TokenFilterContext buffRoot) throws IOException {
            return JsonToken.VALUE_STRING; // Mocked return for coverage
        }

        public void setExposedContext(TokenFilterContext ctxt) {
            try {
                java.lang.reflect.Field field = FilteringParserDelegate.class.getDeclaredField("_exposedContext");
                field.setAccessible(true);
                field.set(this, ctxt);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        public void setHeadContext(TokenFilterContext ctxt) {
            try {
                java.lang.reflect.Field field = FilteringParserDelegate.class.getDeclaredField("_headContext");
                field.setAccessible(true);
                field.set(this, ctxt);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        public void setItemFilter(TokenFilter f) {
            try {
                java.lang.reflect.Field field = FilteringParserDelegate.class.getDeclaredField("_itemFilter");
                field.setAccessible(true);
                field.set(this, f);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    @Before
    public void setUp() {
        delegate = mock(JsonParser.class);
        filter = mock(TokenFilter.class);
        headContext = mock(TokenFilterContext.class);
        delegateUnderTest = new TestableFilteringParserDelegate(delegate, filter, false, true);
        delegateUnderTest.setHeadContext(headContext);
    }

    @Test
    public void testNextToken_BufferedContext_ReturnsToken() throws IOException {
        TokenFilterContext childContext = mock(TokenFilterContext.class);
        when(childContext.nextTokenToRead()).thenReturn(JsonToken.START_OBJECT);
        delegateUnderTest.setExposedContext(childContext);

        JsonToken result = delegateUnderTest.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(childContext).nextTokenToRead();
    }

    @Test
    public void testNextToken_BufferedContext_TraverseChain_ReturnsNullAtEnd() throws IOException {
        TokenFilterContext childContext = mock(TokenFilterContext.class);
        when(childContext.nextTokenToRead()).thenReturn(null);
        when(headContext.findChildOf(childContext)).thenReturn(null);

        // This triggers the "should never occur" exception path
        delegateUnderTest.setExposedContext(childContext);

        try {
            delegateUnderTest.nextToken();
            fail("Should have thrown exception");
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("Unexpected problem"));
        }
    }

    @Test
    public void testNextToken_BufferedContext_HeadContextInArray() throws IOException {
        when(headContext.nextTokenToRead()).thenReturn(null);
        when(headContext.inArray()).thenReturn(true);
        when(delegate.getCurrentToken()).thenReturn(JsonToken.END_ARRAY);

        delegateUnderTest.setExposedContext(headContext);
        JsonToken result = delegateUnderTest.nextToken();

        assertEquals(JsonToken.END_ARRAY, result);
    }

    @Test
    public void testNextToken_NoBufferedContext_NullToken() throws IOException {
        when(delegate.nextToken()).thenReturn(null);

        JsonToken result = delegateUnderTest.nextToken();

        assertNull(result);
    }

    @Test
    public void testNextToken_StartArray_IncludeAll() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        when(filter, when(filter).equals(TokenFilter.INCLUDE_ALL)).thenReturn(true);
        // Note: Mocking enum comparison requires care, usually we just use a real enum

        // Using a real filter to trigger logic
        TestableFilteringParserDelegate delegateWithIncludeAll = new TestableFilteringParserDelegate(delegate, TokenFilter.INCLUDE_ALL, false, true);
        delegateWithIncludeAll.setHeadContext(headContext);
        when(delegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        when(headContext.createChildArrayContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mock(TokenFilterContext.class));

        JsonToken result = delegateWithIncludeAll.nextToken();
        assertEquals(JsonToken.START_ARRAY, result);
    }

    @Test
    public void testNextToken_StartArray_NullFilter_SkipsChildren() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        // Set item filter to null
        delegateUnderTest.setItemFilter(null);

        delegateUnderTest.nextToken();

        verify(delegate).skipChildren();
    }

    @Test
    public void testNextToken_StartObject_IncludeAll() throws IOException {
        TestableFilteringParserDelegate delegateWithIncludeAll = new TestableFilteringParserDelegate(delegate, TokenFilter.INCLUDE_ALL, false, true);
        delegateWithIncludeAll.setHeadContext(headContext);
        when(delegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(headContext.createChildObjectContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mock(TokenFilterContext.class));

        JsonToken result = delegateWithIncludeAll.nextToken();
        assertEquals(JsonToken.START_OBJECT, result);
    }

    @Test
    public void testNextToken_EndArray_ReturnsToken() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.END_ARRAY);
        when(headContext.isStartHandled()).thenReturn(true);

        JsonToken result = delegateUnderTest.nextToken();

        assertEquals(JsonToken.END_ARRAY, result);
        verify(headContext).getParent();
    }

    @Test
    public void testNextToken_FieldName_IncludeAll() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(delegate.getCurrentName()).thenReturn("testField");
        when(headContext.setFieldName("testField")).thenReturn(TokenFilter.INCLUDE_ALL);

        JsonToken result = delegateUnderTest.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
    }

    @Test
    public void testNextToken_FieldName_FilterNull_SkipsChildren() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(delegate.getCurrentName()).thenReturn("testField");
        when(headContext.setFieldName("testField")).thenReturn(null);

        delegateUnderTest.nextToken();

        verify(delegate).nextToken();
        verify(delegate).skipChildren();
    }

    @Test
    public void testNextToken_ScalarValue_IncludeAll() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        delegateUnderTest.setItemFilter(TokenFilter.INCLUDE_ALL);

        JsonToken result = delegateUnderTest.nextToken();

        assertEquals(JsonToken.VALUE_NUMBER_INT, result);
    }

    @Test
    public void testNextToken_ScalarValue_CheckValue_Includes() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        delegateUnderTest.setItemFilter(mock(TokenFilter.class));

        // We need to mock the behavior of the filter for checkValue and includeValue
        TokenFilter mockF = mock(TokenFilter.class);
        delegateUnderTest.setItemFilter(mockF);
        when(headContext.checkValue(mockF)).thenReturn(TokenFilter.INCLUDE_ALL);

        JsonToken result = delegateUnderTest.nextToken();
        assertEquals(JsonToken.VALUE_STRING, result);
    }

    @Test
    public void testNextToken_ScalarValue_NotIncluded_CallsNextToken2() throws IOException {
        when(delegate.nextToken()).thenReturn(JsonToken.VALUE_TRUE);
        delegateUnderTest.setItemFilter(mock(TokenFilter.class));
        when(headContext.checkValue(any())).thenReturn(null);

        JsonToken result = delegateUnderTest.nextToken();

        // result is whatever _nextToken2 returns (mocked as VALUE_STRING in our testable class)
        assertEquals(JsonToken.VALUE_STRING, result);
    }
}
